<script lang="ts">
  import Help from '../components/Help.svelte';
  import type { ElectricityState, ElectricityPoint } from './types';
  import { annual, cost, percent, measured, heating } from './calculator';
  import { number } from '../calendar';
  import { fmt, money, signed } from '../lib/format';
  import { NATIONAL_MONTHLY, ELECTRICITY_REGIONS } from './reference';
  import Field from '../components/Field.svelte';
  import Select from '../components/Select.svelte';
  import Chart from '../components/Chart.svelte';
  let { model, point, onstats }: { model: ElectricityState; point: ElectricityPoint; onstats: (value: ElectricityState['stats']) => string | void } = $props();
  let a = $derived(annual(point, model.year)), saving = $state(5);
  $effect(() => { saving = model.stats.saving; });
  let reduced = $derived(a.projected ? cost(point, a.activeStart, a.activeEnd, a.projected.map(d => ({ ...d, peak: d.peak * (1 - saving / 100), off: d.off * (1 - saving / 100) }))) : null);
  let savings = $derived(a.annualCost?.total !== null && a.annualCost?.total !== undefined && reduced?.total !== null && reduced?.total !== undefined ? Math.max(0, a.annualCost.total - reduced.total) : null);
  let latestChange = $derived(a.latest && a.previous ? percent(a.latest.average, a.previous.average) : null);
  let yoy = $derived(a.prior && a.tracked ? percent(a.tracked.average, a.prior.average) : null);
  let allAnnual = $derived(model.points.map(p => annual(p, model.year)));
  let allVolume = $derived(allAnnual.every(x => x.volume !== null) ? allAnnual.reduce((n, x) => n + x.volume!, 0) : null);
  let regional = $derived(model.stats.region !== 'country' ? (ELECTRICITY_REGIONS[model.stats.region] ?? NATIONAL_MONTHLY) * 12 : null);
  let bars = $derived([
    ...(a.volume !== null ? [{ label: 'Aktív mérő éves adata', short: 'Aktív mérő', value: a.volume, own: true }] : []),
    ...(model.points.length > 1 && allVolume !== null ? [{ label: 'Összes mérő éves adata', short: 'Összes mérő', value: allVolume, own: true }] : []),
    { label: 'Országos átlag · 2025', value: NATIONAL_MONTHLY * 12, own: false },
    ...(regional !== null ? [{ label: `${model.stats.region} · 2025`, value: regional, own: false }] : []),
  ]);
  let eqVolume = $derived(a.latest?.volume ?? 1);
  let deviceMonthly = $derived(model.stats.deviceWatts / 1000 * model.stats.dailyHours * 30);
  let deviceRate = $derived(point.tariff === 'H' && !heating(point.billing.start) ? point.rates.second : point.tariff === 'A2' ? point.rates.low * (1 - point.offPercent / 100) + point.rates.second * point.offPercent / 100 : point.rates.low);
  let headroom = $derived(point.tariff !== 'B_GEO' && a.complete && a.remainingDays > 0 && a.remaining !== null ? a.remaining / a.remainingDays : null);
  let latestCost = $derived(a.latest ? cost(point, a.latest.start, a.latest.end, measured(point, a.latest.start, a.latest.end)) : null);
  let balanceDays = $derived(point.billing.balance.trim() !== '' && latestCost?.total !== null && latestCost?.total !== undefined && latestCost.total > 0 && a.latest ? number(point.billing.balance) / (latestCost.total / a.latest.days) : null);
  const basis = { missing: 'KEVÉS ADAT', measured: 'TELJES MÉRT IDŐSZAK', linear: 'LINEÁRIS ÉVES BECSLÉS', manual: 'MEGADOTT ÉVES BECSLÉS' };
  function update(key: keyof ElectricityState['stats'], raw: string) {
    const value = ['people', 'floorArea', 'region'].includes(key) ? raw.trim() : number(raw);
    return onstats({ ...model.stats, [key]: value });
  }
</script>
<section class="statistics-section" id="electricity-statistics"><div class="statistics-heading"><div><div class="eyebrow"><span class="tiny-line"></span>A SZÁMOK MÖGÖTT</div><h2>A fogyasztásod, új megvilágításban.</h2><p class="section-intro">Az aktív mérési pont statisztikái. Az összes mérőt a közös összesítőben is látod.</p></div><span class="badge neutral">{basis[a.kind]}</span></div>
<details class="card statistics-settings"><summary>Személyes összehasonlítás és készülékpélda <span aria-hidden="true">＋</span></summary><div class="stats-input-grid"><Field id="electricity-people" label="Háztartás létszáma · fő" value={model.stats.people} placeholder="Nem kötelező" decimal oncommit={value => update('people', value)}/><Field id="electricity-floor-area" label="Lakás alapterülete · m²" value={model.stats.floorArea} placeholder="Nem kötelező" decimal oncommit={value => update('floorArea', value)}/><Select id="electricity-region" label="KSH területi referencia" value={model.stats.region} options={[{ value: 'country', label: 'Országos átlag' }, ...Object.keys(ELECTRICITY_REGIONS).sort((a,b) => a.localeCompare(b, 'hu')).map(r => ({ value: r, label: r }))]} oncommit={value => { update('region', value); }}/><Field id="electricity-watts" label="Példakészülék teljesítménye · W" value={model.stats.deviceWatts} decimal oncommit={value => update('deviceWatts', value)}/><Field id="electricity-hours" label="Készülék napi használata · óra" value={model.stats.dailyHours} decimal oncommit={value => update('dailyHours', value)}/></div></details>
<div class="statistics-grid">
<article class="card stat-card"><div class="stat-top"><h3>Napi átlagod</h3><span class="stat-symbol" aria-hidden="true">↗</span></div><div class="stat-number"><span>{fmt(a.latest?.average, 2)}</span><small>kWh/nap</small></div><p class="stat-description">{a.latest ? `${a.latest.start} → ${a.latest.end} · ${a.latest.days} nap · ${fmt(a.latest.volume)} kWh.` : 'Legalább két érvényes mérés szükséges a kiválasztott évhez.'}</p><p class="stat-change">{a.previous ? latestChange === null ? 'Nullás előzményből pozitív fogyasztásnál nincs százalékos osztás.' : `${signed(latestChange)} az előző szakasz napi átlagához képest.` : 'A változás összevetéséhez legalább három mérés kell.'}</p></article>
<article class="card stat-card forecast-card"><div class="stat-top"><h3>Várható éves fogyasztás</h3><span class="stat-symbol" aria-hidden="true">⌁</span></div><span class="badge neutral">{basis[a.kind]}</span><div class="stat-number"><span>{fmt(a.volume)}</span><small>kWh</small></div><p class="stat-description">{a.kind === 'measured' ? 'A jogosult éves időszak pontos nyitó és záró állásából.' : a.kind === 'linear' ? `Legalább 30 nap napi átlagát vetítjük a jogosult év ${a.active} napjára. A használat évszakosan változhat, ezért ez becslés.` : a.kind === 'manual' ? 'A beállított éves becslés, a részéves jogosultság napjaira arányosítva. H-nál a megadott fűtési aránnyal osztunk.' : 'Legalább 30 nap mérés vagy kézi éves becslés kell. H-tarifánál rövid téli/nyári szakaszt nem szorzunk fel az egész évre.'}</p><p class="stat-footnote">Becsült éves költség: {money(a.annualCost?.total)}, alapdíjjal, egyedi időszaki jóváírás nélkül.</p></article>
<article class="card stat-card"><div class="stat-top"><h3>Mennyi fér még bele?</h3><span class="stat-symbol" aria-hidden="true">◷</span></div><div class="stat-number"><span>{fmt(headroom, 2)}</span><small>kWh/nap</small></div><p class="stat-description">{point.tariff === 'B_GEO' ? 'B GEO-nál nincs normál 2523-as sávhatár.' : !a.complete ? `A napi mozgástérhez ${a.activeStart}-i kezdőállás kell.` : a.remainingDays === 0 ? 'Nincs hátralévő nap ebben a lemért jogosultsági időszakban.' : `${fmt(a.remaining)} kWh normál keret és ${a.remainingDays} nap maradt az utolsó méréskor.`}</p><p class="stat-footnote">A H-idény korlátmentes fogyasztása ezen felül értendő. A legutóbbi mérés óta eltelt fogyasztást nem találjuk ki.</p></article>
<article class="card stat-card"><div class="stat-top"><h3>A tavalyi önmagadhoz képest</h3><span class="stat-symbol" aria-hidden="true">↔</span></div><div class="stat-number"><span>{fmt(yoy)}</span><small>%</small></div><p class="stat-description">{a.prior && a.tracked ? `Idei napi átlag: ${fmt(a.tracked.average, 2)}; tavaly: ${fmt(a.prior.average, 2)} kWh.` : a.tracked ? `Tavalyi mérés kell: ${a.priorStart} és ${a.priorEnd}.` : 'Idei és tavalyi mérési szakasz is szükséges.'}</p><p class="stat-footnote">Azonos határnapok napi átlaga, időjárási korrekció nélkül. Február 29. párja február 28.; hiányzó mérésnél nincs interpoláció.</p></article>
<article class="card stat-card benchmark-card"><div class="stat-top"><h3>Magyar átlaghoz képest</h3><span class="badge neutral">KSH · 2025</span></div><p class="stat-description">{a.volume === null ? 'Éves mérés vagy jelölt becslés kell a saját összevetéshez.' : `Aktív mérő: ${fmt(a.volume)} kWh · ${basis[a.kind].toLocaleLowerCase('hu')}.`} Országos referencia: {fmt(NATIONAL_MONTHLY * 12)} kWh/év.</p><Chart id="electricity-benchmark" kind="benchmark" unit="kWh" {bars} label={bars.map(b => `${b.label}: ${fmt(b.value)} kWh/év`).join('. ')}/><p class="stat-change">{a.volume !== null ? `${signed(percent(a.volume, NATIONAL_MONTHLY * 12))} az országos átlaghoz képest.` : ''}</p>{#if a.volume !== null && regional !== null}<p class="stat-footnote">{model.stats.region} átlagához képest: {signed(percent(a.volume, regional))}.</p>{/if}<p class="stat-footnote">Egy háztartási fogyasztóra jutó havi éves átlag × 12. Külön B/H-mérő nem azonos egy teljes háztartással. Több pontnál az ismert összes éves mennyiséget is jelöljük; nem hatékonysági minősítés.</p><a class="stat-source-link" href="https://www.ksh.gov.hu/stadat_files/kor/hu/kor0068.html" target="_blank" rel="noopener noreferrer">KSH · 2025, frissítve: 2026. 10. 30. ↗</a></article>
<article class="card stat-card savings-card"><div class="stat-top"><h3>Kevesebb fogyasztás, kisebb költség</h3><span class="stat-symbol" aria-hidden="true">↘</span></div><div class="saving-heading"><label class="saving-label" for="electricity-saving">Fogyasztáscsökkentés <output for="electricity-saving">{saving}%</output></label><Help forId="electricity-saving" label="Fogyasztáscsökkentés"/></div><input id="electricity-saving" aria-describedby="electricity-saving-help" type="range" min="0" max="100" step="1" bind:value={saving} onchange={() => update('saving', String(saving))} onblur={() => update('saving', String(saving))}/><div class="stat-number"><span>{fmt(savings, 0)}</span><small>Ft/év</small></div><p class="stat-description">{a.annualCost?.total !== null && a.annualCost?.total !== undefined ? `${money(a.annualCost.total)} → ${money(reduced?.total)} becsült éves költség.` : 'Éves fogyasztási adat és modellezhető tarifa szükséges.'}</p><p class="stat-footnote">Az ársávokat és a H-idényt újraszámoljuk, az alapdíj változatlan. Az egyedi időszaki jóváírást nem vetítjük ki az egész évre.</p></article>
<article class="card stat-card"><div class="stat-top"><h3>Szokatlan változás?</h3><span class="stat-symbol" aria-hidden="true">◎</span></div><span class="badge neutral" class:anomaly-warning={a.previous && ((latestChange ?? 0) >= 50 || a.previous.average === 0 && (a.latest?.average ?? 0) > 0)}>{!a.previous ? 'KEVÉS ADAT' : latestChange === null ? 'NULLÁRÓL INDULÓ FOGYASZTÁS' : Math.abs(latestChange) >= 50 ? 'LEGALÁBB 50%-OS VÁLTOZÁS' : 'NINCS 50%-OS ELTÉRÉS'}</span><p class="stat-description">{a.previous && a.latest ? `${fmt(a.previous.average, 2)} → ${fmt(a.latest.average, 2)} kWh/nap két egymást követő mérési szakaszon.` : 'Legalább három mérés kell két szakasz összevetéséhez.'}</p><p class="stat-footnote">Egyszerű figyelemfelhívás. Az időjárás, a készülékek és a mérési hossz is okozhatja; nem hibadiagnózis.</p></article>
<article class="card stat-card"><div class="stat-top"><h3>Egy főre, egy négyzetméterre</h3><span class="stat-symbol" aria-hidden="true">÷</span></div><div class="stat-number"><span>{a.volume !== null && model.stats.people ? fmt(a.volume / number(model.stats.people)) : '—'}</span><small>kWh/fő/év</small></div><p class="stat-description">{a.volume !== null && model.stats.floorArea ? `${fmt(a.volume / number(model.stats.floorArea))} kWh/m²/év.` : 'Az alapterületet és a háztartás létszámát a statisztika beállításai között adhatod meg.'}</p><p class="stat-footnote">Az aktív mérő éves mért vagy becsült energiája. Külön H-mérőnél ez nem a lakás teljes fogyasztása.</p></article>
{#if point.billing.schedule === 'prepaid'}<article class="card stat-card"><div class="stat-top"><h3>Meddig elég az egyenleg?</h3><span class="stat-symbol" aria-hidden="true">◷</span></div><div class="stat-number"><span>{fmt(balanceDays, 0)}</span><small>nap</small></div><p class="stat-description">{balanceDays === null ? 'Add meg az aktuális feltöltött egyenleget, és rögzíts legalább két állást.' : `${money(number(point.billing.balance))} egyenleg a legutóbbi mért napi költség mellett.`}</p><p class="stat-footnote">Átlagalapú becslés, nem élő mérőegyenleg. Nem végzünk feltöltést, és a mérések rögzítése nem von le pénzt.</p></article>{/if}
<article class="card stat-card equivalence-card"><div class="stat-top"><h3>Ez annyi áram, mint…</h3><span class="stat-symbol" aria-hidden="true">≈</span></div><p class="stat-caption">{a.latest ? `A legutóbbi mért ${fmt(eqVolume)} kWh energiája.` : 'Mérés hiányában 1 kWh szemléltetése.'}</p><div class="equivalence-grid"><div><strong>{fmt(eqVolume / (model.stats.deviceWatts / 1000))}</strong><span>óra egy {fmt(model.stats.deviceWatts, 0)} W-os készülékkel</span></div><div><strong>{fmt(deviceMonthly)}</strong><span>kWh / 30 nap, napi {fmt(model.stats.dailyHours)} óra használattal</span></div><div><strong>{money(deviceMonthly * deviceRate)}</strong><span>30 nap fogyasztási díja a kedvezményes egységárral, alapdíj nélkül</span></div></div><p class="stat-footnote">Folyamatos névleges teljesítménnyel szemléltetünk. A termosztátos készülékek és a hűtő működése szakaszos lehet. A példa nem garantált megtakarítás.</p></article>
</div></section>
